function quiltProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:16;
  if(cell<4)cell=4; else if(cell>40)cell=40;
  var out=new Uint8ClampedArray(data.length);
  for(var gy=0;gy<h;gy+=cell) for(var gx=0;gx<w;gx+=cell){
    var cw=Math.min(cell,w-gx), ch=Math.min(cell,h-gy);
    var sr=0,sg=0,sb=0,n=0;
    for(var yy=gy;yy<gy+ch;yy++) for(var xx=gx;xx<gx+cw;xx++){ var p=(yy*w+xx)*4; sr+=data[p]; sg+=data[p+1]; sb+=data[p+2]; n++; }
    var r=Math.round(sr/n), g=Math.round(sg/n), b=Math.round(sb/n);
    var tint=((gx/cell+gy/cell)%2===0)?1.08:0.9;
    for(var py=gy;py<gy+ch;py++) for(var px=gx;px<gx+cw;px++){
      var pp=(py*w+px)*4;
      var onSeam=(px===gx||py===gy||px===gx+cw-1||py===gy+ch-1);
      if(onSeam){ out[pp]=r*0.55; out[pp+1]=g*0.55; out[pp+2]=b*0.55; }
      else { out[pp]=r*tint; out[pp+1]=g*tint; out[pp+2]=b*tint; }
      out[pp+3]=255;
    }
  }
  return out;
}

var EXPORTS={quiltProcess:quiltProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.QuiltForgePure = EXPORTS; }
